import React, { useState, useEffect } from 'react';
import './App.css';

function App() {
  // Auth State
  const [token, setToken] = useState(localStorage.getItem('plateai_token') || '');
  const [user, setUser] = useState(JSON.parse(localStorage.getItem('plateai_user') || 'null'));
  const [isRegistering, setIsRegistering] = useState(false);
  const [authEmail, setAuthEmail] = useState('');
  const [authPassword, setAuthPassword] = useState('');
  const [authName, setAuthName] = useState('');
  const [authError, setAuthError] = useState('');

  // App Navigation & Data State
  const [activeTab, setActiveTab] = useState('overview');
  const [overview, setOverview] = useState(null);
  const [weather, setWeather] = useState(null);
  const [surplusList, setSurplusList] = useState([]);
  const [mealsList, setMealsList] = useState([]);
  const [attendanceList, setAttendanceList] = useState([]);

  // Form states for adding surplus
  const [newFood, setNewFood] = useState('');
  const [newCategory, setNewCategory] = useState('Cooked meal');
  const [newQuantity, setNewQuantity] = useState('');
  const [newStorage, setNewStorage] = useState('');

  // Handle Login / Register
  const handleAuth = async (e) => {
    e.preventDefault();
    setAuthError('');
    const endpoint = isRegistering ? '/api/register' : '/api/login';
    const payload = isRegistering 
      ? { name: authName, email: authEmail, password: authPassword, role: 'Admin' }
      : { email: authEmail, password: authPassword };

    try {
      const res = await fetch(`http://localhost:5000${endpoint}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Authentication failed');

      setToken(data.token);
      setUser(data.user);
      localStorage.setItem('plateai_token', data.token);
      localStorage.setItem('plateai_user', JSON.stringify(data.user));
    } catch (err) {
      setAuthError(err.message);
    }
  };

  const handleLogout = () => {
    setToken('');
    setUser(null);
    localStorage.removeItem('plateai_token');
    localStorage.removeItem('plateai_user');
  };

  // Fetch Main Dashboard Data when authenticated
  useEffect(() => {
    if (!token) return;

    const headers = { 'Authorization': `Bearer ${token}` };

    // Fetch Overview
    fetch('http://localhost:5000/api/overview', { headers })
      .then(res => res.json())
      .then(data => setOverview(data))
      .catch(err => console.error('Overview fetch error:', err));

    // Fetch Weather
    fetch('http://localhost:5000/api/weather/live', { headers })
      .then(res => res.json())
      .then(data => setWeather(data))
      .catch(err => console.error('Weather fetch error:', err));

    // Fetch Surplus Register
    fetch('http://localhost:5000/api/surplus', { headers })
      .then(res => res.json())
      .then(data => {
        if (Array.isArray(data)) setSurplusList(data);
      })
      .catch(err => console.error('Surplus fetch error:', err));

    // Fetch Meals
    fetch('http://localhost:5000/api/meals', { headers })
      .then(res => res.json())
      .then(data => {
        if (Array.isArray(data)) setMealsList(data);
      })
      .catch(err => console.error('Meals fetch error:', err));

    // Fetch Attendance Signals
    fetch('http://localhost:5000/api/attendance-signals', { headers })
      .then(res => res.json())
      .then(data => {
        if (Array.isArray(data)) setAttendanceList(data);
      })
      .catch(err => console.error('Attendance fetch error:', err));

  }, [token]);

  // Handle Verify Surplus Action
  const handleVerifySurplus = async (surplusId) => {
    try {
      const res = await fetch(`http://localhost:5000/api/surplus/${surplusId}/verify`, {
        method: 'PATCH',
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await res.json();
      if (Array.isArray(data)) {
        setSurplusList(data);
      }
    } catch (err) {
      console.error('Verification error:', err);
    }
  };

  // Handle Add Surplus
  const handleAddSurplus = async (e) => {
    e.preventDefault();
    try {
      const res = await fetch('http://localhost:5000/api/surplus', {
        method: 'POST',
        headers: { 
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}` 
        },
        body: JSON.stringify({
          food: newFood,
          category: newCategory,
          quantity: newQuantity,
          storage: newStorage || '7°C\nSafe hold',
          safetyState: 'Needs Verification',
          action: 'Verify'
        })
      });
      const data = await res.json();
      if (Array.isArray(data)) {
        setSurplusList(data);
        setNewFood('');
        setNewQuantity('');
        setNewStorage('');
      }
    } catch (err) {
      console.error('Add surplus error:', err);
    }
  };

  // If not logged in, render Auth Screen
  if (!token) {
    return (
      <div className="auth-container">
        <div className="auth-card">
          <h1>PlateAI Canteen</h1>
          <p>{isRegistering ? 'Create your management account' : 'Sign in to access your canteen dashboard'}</p>
          {authError && <div className="error-banner">{authError}</div>}
          <form onSubmit={handleAuth}>
            {isRegistering && (
              <input 
                type="text" 
                placeholder="Full Name" 
                value={authName} 
                onChange={e => setAuthName(e.target.value)} 
                required 
              />
            )}
            <input 
              type="email" 
              placeholder="Email Address" 
              value={authEmail} 
              onChange={e => setAuthEmail(e.target.value)} 
              required 
            />
            <input 
              type="password" 
              placeholder="Password" 
              value={authPassword} 
              onChange={e => setAuthPassword(e.target.value)} 
              required 
            />
            <button type="submit" className="primary-btn">
              {isRegistering ? 'Register' : 'Login'}
            </button>
          </form>
          <button className="switch-auth-btn" onClick={() => setIsRegistering(!isRegistering)}>
            {isRegistering ? 'Already have an account? Login' : "Don't have an account? Register"}
          </button>
        </div>
      </div>
    );
  }

  // Main Dashboard View
  return (
    <div className="dashboard-container">
      {/* Sidebar Navigation */}
      <aside className="sidebar">
        <h2>PlateAI</h2>
        <p className="user-info">Logged in as: <strong>{user?.name}</strong></p>
        <nav>
          <button className={activeTab === 'overview' ? 'active' : ''} onClick={() => setActiveTab('overview')}>Overview</button>
          <button className={activeTab === 'surplus' ? 'active' : ''} onClick={() => setActiveTab('surplus')}>Surplus Register</button>
          <button className={activeTab === 'meals' ? 'active' : ''} onClick={() => setActiveTab('meals')}>Meals & Service</button>
          <button className={activeTab === 'attendance' ? 'active' : ''} onClick={() => setActiveTab('attendance')}>Attendance Signals</button>
        </nav>
        <button className="logout-btn" onClick={handleLogout}>Logout</button>
      </aside>

      {/* Main Content Area */}
      <main className="content">
        {activeTab === 'overview' && (
          <div className="tab-pane">
            <h2>Canteen Operations Overview</h2>
            <p className="date-banner">{overview?.greetingDate || 'Loading date...'}</p>

            <div className="metrics-grid">
              <div className="metric-card">
                <h3>Expected Demand</h3>
                <p className="metric-value">{overview?.expectedDemand}</p>
              </div>
              <div className="metric-card">
                <h3>Recommended Prep</h3>
                <p className="metric-value">{overview?.recommendedPrep}</p>
              </div>
              <div className="metric-card">
                <h3>Actual Consumption</h3>
                <p className="metric-value">{overview?.actualConsumption}</p>
              </div>
              <div className="metric-card">
                <h3>Safe Surplus</h3>
                <p className="metric-value">{overview?.safeSurplus}</p>
              </div>
            </div>

            {weather && (
              <div className="weather-widget">
                <h3>Live Weather Conditions</h3>
                <p>🌡️ Temperature: <strong>{weather.temperature}°C</strong> | Condition: <strong>{weather.condition}</strong> | Humidity: <strong>{weather.humidity}</strong></p>
              </div>
            )}
          </div>
        )}

        {activeTab === 'surplus' && (
          <div className="tab-pane">
            <h2>Food Surplus & Verification Register</h2>

            <div className="form-card">
              <h3>Record New Surplus Item</h3>
              <form onSubmit={handleAddSurplus} className="inline-form">
                <input type="text" placeholder="Food item name" value={newFood} onChange={e => setNewFood(e.target.value)} required />
                <input type="text" placeholder="Quantity (e.g., 25 meals)" value={newQuantity} onChange={e => setNewQuantity(e.target.value)} required />
                <input type="text" placeholder="Storage conditions (e.g., 7°C)" value={newStorage} onChange={e => setNewStorage(e.target.value)} />
                <button type="submit" className="primary-btn">Save for Verification</button>
              </form>
            </div>

            <div className="table-responsive">
              <table className="data-table">
                <thead>
                  <tr>
                    <th>Food Item</th>
                    <th>Category</th>
                    <th>Quantity</th>
                    <th>Storage State</th>
                    <th>Verification Status</th>
                    <th>Action</th>
                  </tr>
                </thead>
                <tbody>
                  {surplusList.map((item) => (
                    <tr key={item.surplusId || item._id}>
                      <td><strong>{item.food}</strong></td>
                      <td>{item.category}</td>
                      <td>{item.quantity}</td>
                      <td><pre>{item.storage}</pre></td>
                      <td><span className={`badge ${item.safetyState === 'Eligible' ? 'success' : 'warning'}`}>{item.safetyState}</span></td>
                      <td>
                        {item.safetyState !== 'Eligible' ? (
                          <button className="verify-btn" onClick={() => handleVerifySurplus(item.surplusId)}>Verify & Save</button>
                        ) : (
                          <span className="ready-text">Ready</span>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {activeTab === 'meals' && (
          <div className="tab-pane">
            <h2>Scheduled Meals & Services</h2>
            <div className="table-responsive">
              <table className="data-table">
                <thead>
                  <tr>
                    <th>Meal Name</th>
                    <th>Category</th>
                    <th>Service Time</th>
                    <th>Planned Portions</th>
                    <th>Status</th>
                  </tr>
                </thead>
                <tbody>
                  {mealsList.map((meal) => (
                    <tr key={meal.mealId || meal._id}>
                      <td><strong>{meal.name}</strong></td>
                      <td>{meal.category}</td>
                      <td>{meal.service}</td>
                      <td>{meal.planned}</td>
                      <td><span className="badge success">{meal.status}</span></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {activeTab === 'attendance' && (
          <div className="tab-pane">
            <h2>Attendance Signals & Footfall Prediction</h2>
            <div className="table-responsive">
              <table className="data-table">
                <thead>
                  <tr>
                    <th>Date</th>
                    <th>Day</th>
                    <th>Expected Headcount</th>
                    <th>Context / Event</th>
                    <th>Meal Service</th>
                  </tr>
                </thead>
                <tbody>
                  {attendanceList.length > 0 ? (
                    attendanceList.map((sig) => (
                      <tr key={sig._id}>
                        <td>{sig.date}</td>
                        <td>{sig.day}</td>
                        <td><strong>{sig.expected}</strong></td>
                        <td>{sig.context}</td>
                        <td>{sig.meal}</td>
                      </tr>
                    ))
                  ) : (
                    <tr>
                      <td colSpan="5" className="empty-text">No attendance signals recorded yet.</td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

export default App;
